def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    wall = next(v for row in grid for v in row if v != bg)

    # The parallel diagonal strokes have constant (column - row) offsets.
    # Fill the gaps between neighboring strokes wherever both are present.
    offsets = sorted({
        c - r
        for r, row in enumerate(grid)
        for c, value in enumerate(row)
        if value == wall
    })
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        present = {c - r for c, value in enumerate(row) if value == wall}
        for a, b in zip(offsets, offsets[1:]):
            if a in present and b in present:
                for c in range(r + a + 1, r + b):
                    if 0 <= c < w and out[r][c] == bg:
                        out[r][c] = 2
    return out
